-- Fictional training data generated for the LumaPay manual testing project.
-- Safe to run more than once: rows with existing primary keys are skipped.

-- LumaPay synthetic fintech dataset, generated locally for SQL practice.
-- Run this script once in MySQL Workbench. It creates a separate lumapay_practice schema.

-- LumaPay synthetic fintech practice schema.
-- Create this separate schema; it does not overwrite the earlier QA ads dataset.
CREATE DATABASE IF NOT EXISTS lumapay_practice
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lumapay_practice;

CREATE TABLE IF NOT EXISTS customers (
  customer_id VARCHAR(12) PRIMARY KEY,
  full_name VARCHAR(100) NOT NULL,
  email VARCHAR(160) NOT NULL,
  country CHAR(2) NOT NULL,
  kyc_status VARCHAR(20) NOT NULL,
  created_at DATETIME NOT NULL
);

CREATE TABLE IF NOT EXISTS accounts (
  account_id VARCHAR(12) PRIMARY KEY,
  customer_id VARCHAR(12) NOT NULL,
  account_type VARCHAR(20) NOT NULL,
  currency CHAR(3) NOT NULL,
  opening_balance DECIMAL(14,2) NOT NULL,
  balance DECIMAL(14,2) NOT NULL,
  account_status VARCHAR(20) NOT NULL,
  opened_at DATETIME NOT NULL,
  CONSTRAINT fk_accounts_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE IF NOT EXISTS transactions (
  transaction_id VARCHAR(16) PRIMARY KEY,
  account_id VARCHAR(12) NOT NULL,
  counterparty VARCHAR(100) NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  currency CHAR(3) NOT NULL,
  transaction_type VARCHAR(20) NOT NULL,
  direction VARCHAR(10) NOT NULL,
  status VARCHAR(20) NOT NULL,
  channel VARCHAR(20) NOT NULL,
  risk_score TINYINT NOT NULL,
  created_at DATETIME NOT NULL,
  CONSTRAINT fk_transactions_account FOREIGN KEY (account_id) REFERENCES accounts(account_id)
);

CREATE TABLE IF NOT EXISTS fraud_alerts (
  alert_id VARCHAR(16) PRIMARY KEY,
  transaction_id VARCHAR(16) NOT NULL,
  reason VARCHAR(100) NOT NULL,
  severity VARCHAR(12) NOT NULL,
  status VARCHAR(20) NOT NULL,
  created_at DATETIME NOT NULL,
  CONSTRAINT fk_alerts_transaction FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id)
);



-- 300 rows: customers

-- 600 rows: accounts

-- 12000 rows: transactions

-- 500 rows: fraud_alerts

-- Expected row counts: customers 300, accounts 600, transactions 12000, fraud_alerts 500.
SELECT 'customers' AS table_name, COUNT(*) AS row_count FROM customers
UNION ALL SELECT 'accounts', COUNT(*) FROM accounts
UNION ALL SELECT 'transactions', COUNT(*) FROM transactions
UNION ALL SELECT 'fraud_alerts', COUNT(*) FROM fraud_alerts;
